/* Shared tool shell. Original fields, drafts and API contracts stay intact. */
function v4BookNames(id){return v2Tool(id).sources.filter(k=>!['lecture','hall','mendelow','peirce','klein','trust'].includes(k)).map(k=>V2.sources[k].name);}
v2SourceTags=id=>`<div class="v2-source-tags">${v4BookNames(id).map(name=>`<span>${esc(name)}</span>`).join('')}</div>`;
header=()=>`<header class="studio-header hybrid-header v3-header v4-header"><a href="#home" class="wordmark" aria-label="PINA home">PINA</a><nav aria-label="Main navigation"><div class="v4-tool-nav"><button type="button" data-v4-menu aria-expanded="false" aria-controls="v4-menu">Tools <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button><div id="v4-menu" class="v4-mega-menu" hidden>${TOOL_GROUPS.map(([name,ids])=>`<section><h2>${esc(name)}</h2>${ids.map(id=>`<a href="${hybridHref(id)}">${esc(v2Tool(id).name)}</a>`).join('')}</section>`).join('')}<a class="v4-all-tools" href="#home/0/tools">Explore all tools →</a></div></div><a href="#notebook">My notebook</a><a href="#shelf">Research</a></nav></header>`;
typePicker3=(value='auto',where='home')=>`<label class="type-picker"><select aria-label="Type of message" data-chat-type="${where}"><option value="auto" ${value==='auto'?'selected':''}>Find the best fit</option>${ROUTES3.map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
tabs3=(id,active)=>`<nav class="v3-tool-tabs" aria-label="Tool sections">${[['learn','Learn it',v2LearnHref(id)],['case',id===6?'Studio case study':'Netflix case study',v2CaseHref(id)],['project','Use it on my project',v2WorkHref(id)]].map(([key,label,href])=>`<a href="${href}" ${key===active?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
page3=function(html,id,active){let body=html.match(/<main[^>]*>([\s\S]*?)<\/main>/)?.[1]||html;body=body.replace(/<div class="map-page-head">[\s\S]*?<\/div>/,'').replace(/<div class="chapter-top">[\s\S]*?<\/div><\/div>/,'').replace(/<nav class="draft-breadcrumbs"[\s\S]*?<\/nav>/,'');const isGrid=/data-v2-learn|data-v2-work|v4-case-grid/.test(body);return shell(`${tabs3(id,active)}<header class="v4-tool-heading"><div><h1>${esc(v2Tool(id).name)}</h1><div class="v3-frameworks" aria-label="Frameworks behind this tool">${hybridTags(id)}</div></div>${active==='project'?more3(restartButton(id)):''}</header>${body}${active==='case'&&isGrid?'<div class="v4-case-baseline" aria-hidden="true"></div>':''}`,`v2-page v3-tool-page v4-tool-page ${active==='learn'?'map-page v4-learn':active==='project'?'make-page v3-project v4-project':'case-page v4-case-page'} ${isGrid?'':'v4-no-grid'}`);};
function v4CaseMap(id){const previous=work;try{work={...projectExample(id),ledger:previous.ledger};return v2Map(id,'work',-1);}finally{work=previous;}}
case3=function(id){const t=v2Tool(id),c=CASES.find(c=>c.id===['ads','sharing','artwork','sharing','artwork','ads','value'][id]);let body;if(id<7)body=`<p class="case-line">${esc(c.quote)}</p><section><h2>What ${id===6?'the studio':'Netflix'} intended</h2><p>${esc(c.meant)}</p></section><section><h2>How people could read it</h2><p>${esc(c.read)}</p></section><section><h2>What the tool reveals</h2><p>${esc(SOURCE_CONTENT[id].lesson||c.lesson)}</p></section><section><h2>What could change</h2><p>${esc(c.fix)}</p></section>${id===2?framePromiseCase():''}`;else{const p=ANYTIME_SOURCE[id].case;body=`<section><h2>What Netflix intended</h2><p>${esc(p[0])}</p></section><section><h2>How people could read it</h2><p>${esc(p[1]||p[0])}</p></section><section><h2>What the tool reveals</h2><p>${esc(t.reading)}</p></section><section><h2>What could change</h2><p>${esc(CASE_CHANGE3[id]||t.steps.at(-1).why)}</p></section>`;}return page3(shell(`<section class="v4-case-grid"><aside class="v4-case-visual"><div class="v2-live" data-v2-map="${id}" role="img" aria-label="${esc(t.name)} example diagram">${v4CaseMap(id)}</div></aside><article class="v4-case-copy" tabindex="0" aria-label="Case study"><p class="eyebrow">${id===6?'STUDIO':'NETFLIX'} CASE STUDY</p>${body}<div class="v4-case-footer"><p class="v3-case-sources">Sources: ${esc(v4BookNames(id).join(' · '))}.</p><a class="ink-button primary" href="${v2WorkHref(id)}">Try it on my project →</a></div></article></section>`),id,'case');};
toolCase=case3;
const map4=v2Map;v2Map=function(id,mode='work',part=-1){if(id===13&&mode==='learn')return `<div class="v4-three-concept"><svg viewBox="0 0 600 420" role="img" aria-label="Ethics, emotion and economics shape how a message is received"><path d="M140 110 460 110 300 340Z" fill="#f0f3e7" stroke="#96ae91" stroke-width="2"/><path d="M300 185 140 110M300 185 460 110M300 185 300 340" stroke="#b8cbb0"/><circle cx="300" cy="185" r="46" fill="#fffef9" stroke="#7f9b77"/><text x="300" y="191" text-anchor="middle">A decision</text>${[[140,110,'Ethics','What feels fair?','#dce8d5'],[460,110,'Emotion','What feels at stake?','#eadbc6'],[300,340,'Economics','What does it cost?','#d6e6ed']].map(([x,y,title,sub,color],i)=>`<g data-v2-map-part="${i+1}" role="button" tabindex="0" aria-label="Explain ${title}"><rect x="${x-105}" y="${y-37}" width="210" height="74" rx="8" fill="${color}" stroke="#91a58a"/><text x="${x}" y="${y-3}" text-anchor="middle" font-weight="600">${title}</text><text x="${x}" y="${y+21}" text-anchor="middle" font-size="14">${sub}</text></g>`).join('')}</svg><p>One message can appeal to three different priorities.</p></div>`;let html=map4(id,mode,part);if(id===14)html=html.replace(/<h2>[\s\S]*?<\/h2>/,'');return html;};
const v4StaticMap=staticMap3;staticMap3=function(){v4StaticMap();document.querySelectorAll('.v4-case-visual [data-v2-map]').forEach(map=>{map.querySelectorAll('button').forEach(b=>{const n=document.createElement('div');n.className=b.className;n.innerHTML=b.innerHTML;b.replaceWith(n);});map.querySelectorAll('input').forEach(n=>n.disabled=true);map.querySelectorAll('[data-v2-map-part],[data-map-step],[data-any-part],[tabindex]').forEach(n=>{['data-v2-map-part','data-map-step','data-any-part','tabindex','role'].forEach(a=>n.removeAttribute(a));});});};
const v4Bind=bind;bind=function(){v4Bind();const toggle=document.querySelector('[data-v4-menu]'),menu=document.querySelector('#v4-menu'),nav=toggle?.parentElement;if(toggle&&menu){let timer;const set=open=>{menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));};toggle.onclick=()=>set(menu.hidden);nav.addEventListener('pointerenter',()=>{if(matchMedia('(hover: hover)').matches){clearTimeout(timer);set(true);}});nav.addEventListener('pointerleave',()=>{timer=setTimeout(()=>{if(!nav.contains(document.activeElement))set(false);},140);});nav.addEventListener('focusout',e=>{if(!nav.contains(e.relatedTarget))set(false);});nav.addEventListener('keydown',e=>{if(e.key==='Escape'){set(false);toggle.focus();}});}document.querySelectorAll('.v4-project .map-speaker,.v4-project .input-caption').forEach(n=>n.remove());const root=document.querySelector('[data-v2-work]'),id=Number(root?.dataset.v2Work),screen=root?.dataset.v2Screen;if(root&&id===14&&screen!=='context'&&screen!=='notes'&&screen!=='output'&&!root.querySelector('.v2-reading-card')&&!root.querySelector('#s14_think'))root.querySelector('.v2-answer-sheet>h1')?.insertAdjacentHTML('afterend',v2ReadingCard(14,false));if(root&&id===5)root.querySelectorAll('.v2-field textarea').forEach(n=>n.rows=2);const learn=document.querySelector('[data-v2-learn]');if(learn){const part=Number(learn.dataset.v2Part);learn.querySelectorAll('[data-v2-map-part],[data-map-step],[data-any-part]').forEach(n=>n.setAttribute('aria-pressed',String(Number(n.dataset.v2MapPart??n.dataset.mapStep??n.dataset.anyPart)===part)));}if(root&&id===14){const think=root.querySelector('#s14_think');if(think&&!root.querySelector('.v4-think-reading'))think.insertAdjacentHTML('beforebegin','<details class="v4-think-reading"><summary>How the reading solves this</summary><p>Separate what this person has said from what you infer they believe. Write a possible thought, then mark it as inferred and check it with them.</p><small>Persuasion</small></details>');}staticMap3();scheduleMapLayout();};
const v4ChatRender=chatRender;chatRender=function(){v4ChatRender();document.querySelectorAll('.chat3-message').forEach((n,i)=>{const m=chat3.messages[i],label=n.querySelector('.chat3-reading small');if(m?.reading&&label)label.textContent=v4BookNames(m.tool).join(' · ');});requestAnimationFrame(scheduleMapLayout);const close=document.querySelector('[data-chat-close]');if(close)close.innerHTML=ic('close');};
// Resize the connectors when a chat drawer changes available diagram space.
if(typeof ResizeObserver!=='undefined'){const mapResize4=new ResizeObserver(()=>scheduleMapLayout());const bindResize4=bind;bind=function(){bindResize4();mapResize4.disconnect();document.querySelectorAll('.v4-tool-page [data-v2-map]').forEach(n=>mapResize4.observe(n));};}
document.addEventListener('click',e=>{if(!e.target.closest('.v4-tool-nav')){const menu=document.querySelector('#v4-menu');if(menu){menu.hidden=true;document.querySelector('[data-v4-menu]')?.setAttribute('aria-expanded','false');}}});
route();
